/**
 * Beam 최소 인장 철근
 * KDS 14 20 50 / ACI 318-19 §9.6.1.2
 */

/**
 * @param {object} p
 * @param {number} p.fck_mpa    콘크리트 압축강도 (MPa)
 * @param {number} p.fy_mpa     철근 항복강도 (MPa)
 * @param {number} p.bw_mm      복부 폭 (mm)
 * @param {number} p.d_mm       유효 깊이 (mm)
 * @param {number} p.fpc_psi    콘크리트 압축강도 (psi)
 * @param {number} p.fy_ksi     철근 항복강도 (ksi)
 * @param {number} p.bw_in      복부 폭 (in)
 * @param {number} p.d_in       유효 깊이 (in)
 * @param {Array}  p.rebarMetric
 * @param {Array}  p.rebarImperial
 * @returns {{ metric, imperial }}
 */
export function calcBeamReinf({ fck_mpa, fy_mpa, bw_mm, d_mm, fpc_psi, fy_ksi, bw_in, d_in, rebarMetric, rebarImperial }) {
  // ── KDS 14 20 50 / ACI 318-19 SI ──
  let metric = null;
  if (fck_mpa > 0 && fy_mpa > 0 && bw_mm > 0 && d_mm > 0
      && isFinite(fck_mpa) && isFinite(fy_mpa)) {
    const term1 = (0.25 * Math.sqrt(fck_mpa) / fy_mpa) * bw_mm * d_mm;
    const term2 = (1.4 / fy_mpa) * bw_mm * d_mm;
    const As_min = Math.max(term1, term2);
    if (isFinite(As_min) && As_min > 0) {
      metric = {
        As_min,
        governs: term1 >= term2 ? '0.25√fck/fy' : '1.4/fy',
        rebars: rebarMetric.map(bar => ({
          name: bar.name,
          count: Math.ceil(As_min / bar.area_mm2),
        })),
      };
    }
  }

  // ── ACI 318-19 US Customary ──
  let imperial = null;
  if (fpc_psi > 0 && fy_ksi > 0 && bw_in > 0 && d_in > 0
      && isFinite(fpc_psi) && isFinite(fy_ksi)) {
    const fy_psi = fy_ksi * 1000;
    const term1 = (3 * Math.sqrt(fpc_psi) / fy_psi) * bw_in * d_in;
    const term2 = (200 / fy_psi) * bw_in * d_in;
    const As_min = Math.max(term1, term2);
    if (isFinite(As_min) && As_min > 0) {
      imperial = {
        As_min,
        governs: term1 >= term2 ? '3√f\'c/fy' : '200/fy',
        rebars: rebarImperial.map(bar => ({
          name: bar.name,
          count: Math.ceil(As_min / bar.area_in2),
        })),
      };
    }
  }

  return { metric, imperial };
}
