import { useState, useMemo } from 'react'
import UnitInput from '../../components/shared/UnitInput'
import ResultBox from '../../components/shared/ResultBox'
import { calcBeamReinf } from '../../engines/beamReinf'

const REBAR_METRIC   = [
  { name: 'D10', area_mm2: 71.3 }, { name: 'D13', area_mm2: 126.7 },
  { name: 'D16', area_mm2: 198.6 }, { name: 'D19', area_mm2: 284.9 },
  { name: 'D22', area_mm2: 387.1 }, { name: 'D25', area_mm2: 506.7 },
]
const REBAR_IMPERIAL = [
  { name: '#3', area_in2: 0.11 }, { name: '#4', area_in2: 0.20 },
  { name: '#5', area_in2: 0.31 }, { name: '#6', area_in2: 0.44 },
  { name: '#7', area_in2: 0.60 }, { name: '#8', area_in2: 0.79 },
]

const MM_TO_IN = 0.03937
const MPA_TO_PSI = 145.038

export default function BeamView() {
  const [fck, setFck] = useState('24')
  const [fy,  setFy]  = useState('400')
  const [bw,  setBw]  = useState('300')
  const [d,   setD]   = useState('500')

  const vals = {
    fck_mpa: parseFloat(fck) || 0,
    fy_mpa:  parseFloat(fy)  || 0,
    bw_mm:   parseFloat(bw)  || 0,
    d_mm:    parseFloat(d)   || 0,
    fpc_psi: (parseFloat(fck) || 0) * MPA_TO_PSI,
    fy_ksi:  (parseFloat(fy)  || 0) * 0.145038,
    bw_in:   (parseFloat(bw)  || 0) * MM_TO_IN,
    d_in:    (parseFloat(d)   || 0) * MM_TO_IN,
    rebarMetric: REBAR_METRIC,
    rebarImperial: REBAR_IMPERIAL,
  }

  const result = useMemo(() => calcBeamReinf(vals), [fck, fy, bw, d])

  return (
    <div>
      <h3 style={titleStyle}>BEAM — Min. Tensile Reinforcement</h3>
      <p style={descStyle}>KDS 14 20 50 / ACI 318-19 §9.6.1.2</p>

      <div className="grid md:grid-cols-2 gap-8">
        {/* KS */}
        <div style={cardKS}>
          <h4 style={{ fontSize: 14, fontWeight: 700, marginBottom: 14, color: 'var(--ac-main)' }}>🇰🇷 KS CODE (METRIC)</h4>
          <UnitInput id="beam-fck" label="Concrete Strength f'c" unit="MPa" value={fck} onChange={setFck} />
          <UnitInput id="beam-fy"  label="Steel Yield Strength fy" unit="MPa" value={fy}  onChange={setFy}  />
          <UnitInput id="beam-bw"  label="Web Width bw"            unit="mm"  value={bw}  onChange={setBw}  />
          <UnitInput id="beam-d"   label="Effective Depth d"        unit="mm"  value={d}   onChange={setD}   />
          {result?.metric && (
            <ResultBox title="Min. Tensile Steel As,min (KDS)" accent>
              <p style={{ fontSize: 15, marginBottom: 8, color: 'var(--tx-primary)' }}>
                As,min = <span style={{ fontWeight: 700, color: 'var(--val-pos)' }}>
                  {result.metric.As_min.toFixed(0)} mm²
                </span>
                <span style={{ fontSize: 11, color: 'var(--tx-muted)', marginLeft: 8 }}>
                  (governs: {result.metric.governs})
                </span>
              </p>
              <h5 style={subLabel}>D-Bar Count</h5>
              <RebarCount items={result.metric.rebars} />
            </ResultBox>
          )}
        </div>

        {/* ACI */}
        <div style={cardACI}>
          <h4 style={{ fontSize: 14, fontWeight: 700, marginBottom: 14, color: 'var(--tx-primary)' }}>🇺🇸 ACI CODE (IMPERIAL)</h4>
          <p style={{ fontSize: 11, color: 'var(--tx-muted)', marginBottom: 10, padding: '4px 8px', background: 'var(--bg-inset)', borderRadius: 4 }}>
            ↩ Auto-converted from KS inputs (read-only)
          </p>
          <ReadOnlyField label="f'c" unit="psi" value={vals.fpc_psi.toFixed(0)} />
          <ReadOnlyField label="fy"  unit="ksi" value={vals.fy_ksi.toFixed(2)} />
          <ReadOnlyField label="bw"  unit="in"  value={vals.bw_in.toFixed(2)} />
          <ReadOnlyField label="d"   unit="in"  value={vals.d_in.toFixed(2)} />
          {result?.imperial && (
            <ResultBox title="Required Min. Steel Area As,min (ACI)">
              <p style={{ fontSize: 15, marginBottom: 8, color: 'var(--tx-primary)' }}>
                As,min = <span style={{ fontWeight: 700, color: 'var(--val-pos)' }}>
                  {result.imperial.As_min.toFixed(3)} in²
                </span>
                <span style={{ fontSize: 11, color: 'var(--tx-muted)', marginLeft: 8 }}>
                  (governs: {result.imperial.governs})
                </span>
              </p>
              <h5 style={subLabel}>#-Bar Count</h5>
              <RebarCount items={result.imperial.rebars} />
            </ResultBox>
          )}
        </div>
      </div>
    </div>
  )
}

// 읽기 전용 변환값 표시 — disabled 스타일로 편집 불가 명시
function ReadOnlyField({ label, unit, value }) {
  return (
    <div style={{ marginBottom: 12 }}>
      <label style={{ display: 'block', fontSize: 12, color: 'var(--tx-muted)', marginBottom: 3 }}>
        {label} ({unit})
      </label>
      <div style={{
        background: 'var(--bg-inset)', border: '1px dashed var(--bd-subtle)',
        borderRadius: 6, padding: '6px 10px', textAlign: 'center',
        fontSize: 14, fontWeight: 600, color: 'var(--ac-main)',
        cursor: 'not-allowed', opacity: 0.75,
      }}>
        {value}
      </div>
    </div>
  )
}

function RebarCount({ items }) {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
      {items.map(b => (
        <div key={b.name} style={{
          background: 'var(--bg-inset)', borderRadius: 6, padding: '6px 12px',
          display: 'flex', justifyContent: 'space-between', alignItems: 'center',
        }}>
          <span style={{ color: 'var(--tx-secondary)', fontSize: 12, fontWeight: 600 }}>{b.name}</span>
          <span style={{ fontWeight: 700, color: 'var(--val-pos)', fontSize: 13 }}>{b.count}-{b.name}</span>
        </div>
      ))}
    </div>
  )
}

const titleStyle = { fontSize: '1.3rem', fontWeight: 700, marginBottom: 8, color: 'var(--tx-primary)', paddingBottom: 10, borderBottom: '1px solid var(--bd-subtle)' }
const descStyle  = { marginBottom: 20, color: 'var(--tx-secondary)', fontSize: 13 }
const subLabel   = { fontSize: 11, fontWeight: 600, color: 'var(--tx-secondary)', marginTop: 12, marginBottom: 6, paddingTop: 10, borderTop: '1px solid var(--bd-subtle)' }
const cardBase = { background: 'var(--bg-card)', border: '1px solid', borderRadius: 10, padding: 20 }
const cardKS   = { ...cardBase, borderColor: 'var(--bd-accent)' }
const cardACI  = { ...cardBase, borderColor: 'var(--bd-muted)' }
